// Prepare Groq AI prompt
const input = $input.first().json.body || $input.first().json;

const prompt = `Parse this viewing request:

Client Message: ${input.message || ''}
Client Name: ${input.name || ''}
Client Phone: ${input.phone || ''}
Client Email: ${input.email || ''}

Extract and return JSON:
{
  "intent": "schedule|reschedule|cancel|inquiry",
  "property_reference": "address or ID mentioned",
  "property_confidence": 0.0-1.0,
  "preferred_dates": [
    {
      "date": "YYYY-MM-DD or relative (today, tomorrow, this weekend)",
      "time_preference": "morning|afternoon|evening|specific time",
      "flexibility": "strict|flexible"
    }
  ],
  "urgency": "high|medium|low",
  "party_size": 0,
  "special_requirements": ["wheelchair access", "after hours", etc],
  "client_type": "serious_buyer|curious|investor|first_time",
  "suggested_response": "confirmation message draft"
}`;

return {
  json: {
    prompt: prompt,
    client_data: input
  }
};

// Parse Groq response and extract AI parsed data
const groqResponse = $input.first().json;
const clientData = $('Prepare Groq Prompt').first().json.client_data;

let parsedData;
try {
  // Groq returns content in choices[0].message.content
  const content = groqResponse.choices?.[0]?.message?.content || groqResponse.content;
  parsedData = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  return {
    json: {
      error: 'Failed to parse AI response',
      raw_response: groqResponse,
      client_data: clientData
    }
  };
}

// Resolve relative dates to actual dates
function resolveDate(dateStr) {
  const today = new Date();
  const dayNames = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];

  const dateStrLower = dateStr.toLowerCase().trim();

  // Handle 'today'
  if (dateStrLower === 'today') {
    return today.toISOString().split('T')[0];
  }

  // Handle 'tomorrow'
  if (dateStrLower === 'tomorrow') {
    const tomorrow = new Date(today);
    tomorrow.setDate(today.getDate() + 1);
    return tomorrow.toISOString().split('T')[0];
  }

  // Handle 'this weekend' (Saturday)
  if (dateStrLower === 'this weekend') {
    const saturday = new Date(today);
    saturday.setDate(today.getDate() + (6 - today.getDay()));
    return saturday.toISOString().split('T')[0];
  }

  // Handle 'next week' (next Monday)
  if (dateStrLower === 'next week') {
    const nextMonday = new Date(today);
    nextMonday.setDate(today.getDate() + ((8 - today.getDay()) % 7 || 7));
    return nextMonday.toISOString().split('T')[0];
  }

  // Handle day names (e.g., 'next tuesday')
  for (const day of dayNames) {
    if (dateStrLower.includes(day)) {
      const targetDayIndex = dayNames.indexOf(day);
      const currentDayIndex = today.getDay();
      let daysToAdd = targetDayIndex - currentDayIndex;

      if (dateStrLower.includes('next') || daysToAdd <= 0) {
        daysToAdd += 7;
      }

      const targetDate = new Date(today);
      targetDate.setDate(today.getDate() + daysToAdd);
      return targetDate.toISOString().split('T')[0];
    }
  }

  // Assume it's already in YYYY-MM-DD format
  return dateStr;
}

// Process preferred dates
const resolvedDates = (parsedData.preferred_dates || []).map(d => ({
  ...d,
  resolved_date: resolveDate(d.date)
}));

// Generate suggested time slots based on preferences
function generateTimeSlots(timePreference) {
  const slots = [];
  switch (timePreference) {
    case 'morning':
      slots.push('09:00', '10:30', '11:30');
      break;
    case 'afternoon':
      slots.push('13:00', '14:30', '16:00');
      break;
    case 'evening':
      slots.push('17:00', '17:30', '18:00');
      break;
    default:
      // Mixed/default
      slots.push('10:00', '14:00', '16:00');
  }
  return slots;
}

const enrichedData = {
  ...parsedData,
  preferred_dates: resolvedDates.map(d => ({
    ...d,
    suggested_slots: generateTimeSlots(d.time_preference)
  })),
  client_data: clientData,
  parsed_at: new Date().toISOString()
};

return {
  json: enrichedData
};

// Match preferred slots with agent availability
const parsedData = $input.first().json;
const availabilityData = $('Query Agent Availability').all();

// Default agent availability if no record found
const defaultSlots = ['09:00', '10:00', '11:00', '12:00', '13:00', '14:00', '15:00', '16:00', '17:00'];

// Get available slots from database or use defaults
let availableSlots = defaultSlots;
let agentId = null;
let bookedSlots = [];

if (availabilityData.length > 0 && availabilityData[0].json) {
  const agentRecord = availabilityData[0].json;
  availableSlots = agentRecord.available_slots || defaultSlots;
  bookedSlots = agentRecord.booked_slots || [];
  agentId = agentRecord.agent_id;
}

// Filter out booked slots
const freeSlots = availableSlots.filter(slot => !bookedSlots.includes(slot));

// Get preferred time preference
const timePreference = parsedData.preferred_dates?.[0]?.time_preference || 'any';
const urgency = parsedData.urgency || 'medium';

// Match slots based on preference
let matchedSlots = [];

if (timePreference === 'morning') {
  matchedSlots = freeSlots.filter(t => {
    const hour = parseInt(t.split(':')[0]);
    return hour >= 8 && hour < 12;
  });
} else if (timePreference === 'afternoon') {
  matchedSlots = freeSlots.filter(t => {
    const hour = parseInt(t.split(':')[0]);
    return hour >= 12 && hour < 17;
  });
} else if (timePreference === 'evening') {
  matchedSlots = freeSlots.filter(t => {
    const hour = parseInt(t.split(':')[0]);
    return hour >= 17;
  });
} else {
  matchedSlots = freeSlots;
}

// Take top 3 slots
const suggestedSlots = matchedSlots.slice(0, 3).map(slot => ({
  time: slot,
  date: parsedData.preferred_dates?.[0]?.resolved_date,
  datetime: `${parsedData.preferred_dates?.[0]?.resolved_date}T${slot}:00`,
  confidence: 0.9
}));

// If no slots match preference, suggest alternatives
if (suggestedSlots.length === 0 && freeSlots.length > 0) {
  suggestedSlots.push(
    ...freeSlots.slice(0, 3).map(slot => ({
      time: slot,
      date: parsedData.preferred_dates?.[0]?.resolved_date,
      datetime: `${parsedData.preferred_dates?.[0]?.resolved_date}T${slot}:00`,
      confidence: 0.6,
      note: 'Alternative time outside preference'
    }))
  );
}

return {
  json: {
    parsed_data: parsedData,
    agent_id: agentId,
    suggested_slots: suggestedSlots,
    total_available: freeSlots.length,
    slots_found: suggestedSlots.length > 0,
    urgency: urgency
  }
};

// Generate confirmation message
const data = $('Match Slots').item.json;
const parsed = data.parsed_data;

const slots = data.suggested_slots.map((slot, index) => {
  const time = slot.time;
  const date = new Date(slot.date).toLocaleDateString('en-ZA', {
    weekday: 'long',
    day: 'numeric',
    month: 'long'
  });
  return `${index + 1}. ${date} at ${time}`;
}).join('\n');

const propertyRef = parsed.property_reference || 'your requested property';
const clientName = parsed.client_data?.name || 'there';

let message = `Hi ${clientName},\n\n`;
message += `Great! I've found ${data.suggested_slots.length} available time slots for viewing ${propertyRef}:`;
message += `\n\n${slots}\n\n`;
message += `Please reply with the number (1, 2, or 3) of your preferred time, or let me know if none work for you.\n\n`;
message += `Your reference: #${Math.random().toString(36).substr(2, 6).toUpperCase()}`;

return {
  json: {
    message: message,
    to: parsed.client_data?.phone || parsed.client_data?.email,
    request_id: data.request_id,
    slots: data.suggested_slots
  }
};

// Alternative dates message
const data = $('Match Slots').item.json;
const parsed = data.parsed_data;
const clientName = parsed.client_data?.name || 'there';

let message = `Hi ${clientName},\n\n`;
message += `I couldn't find availability for your preferred time. `;

if (data.total_available > 0) {
  message += `However, I have ${data.total_available} other slots available on that day.`;
} else {
  message += `Would you like me to check the next available day?`;
}

message += `\n\nPlease let me know some alternative times that might work for you.`;

return {
  json: {
    message: message,
    to: parsed.client_data?.phone || parsed.client_data?.email,
    alternative_requested: true
  }
};
